def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    rem = 100 - n
    if rem <= 0:
        return 'D'

    opp_c = 0
    my_c = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1

    opp_rate = opp_c / n
    my_rate = my_c / n
    last_my, last_opp = history[-1]

    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    c_w = 0.0
    d_w = 0.0
    cc_w = 0.0
    dc_w = 0.0
    after_dc = 0
    after_dd = 0
    total_dr = 0

    if n > 1:
        denom = n - 1
        for i in range(1, n):
            pm = history[i - 1][0]
            o = history[i][1]
            w = 1.0 + 2.0 * (i / denom)

            if pm == 'C':
                c_w += w
                if o == 'C':
                    cc_w += w
            else:
                d_w += w
                total_dr += 1
                if o == 'C':
                    after_dc += 1
                    dc_w += w
                else:
                    after_dd += 1

    prior_c = 0.88 + 0.05 * opp_rate
    prior_d = 0.05 + 0.08 * opp_rate
    alpha = 3.5

    qC = (cc_w + alpha * prior_c) / (c_w + alpha)
    qD = (dc_w + alpha * prior_d) / (d_w + alpha)

    if qC < 0.0:
        qC = 0.0
    elif qC > 1.0:
        qC = 1.0

    if qD < 0.0:
        qD = 0.0
    elif qD > 1.0:
        qD = 1.0

    if opp_rate < 0.30:
        if qC > 0.35:
            qC = 0.35
        if qD > 0.35:
            qD = 0.35

    if after_dd > after_dc:
        if qD > 0.22:
            qD = 0.22

    if opp_rate > 0.75 and after_dc > after_dd and last_opp == 'C':
        if qD < 0.60:
            qD = 0.60

    V0 = 0.0
    V1 = 0.0
    for _ in range(1, rem):
        best0 = 3.0 * qC + V0
        cand = 1.0 + 4.0 * qC + V1
        if cand > best0:
            best0 = cand

        best1 = 3.0 * qD + V0
        cand = 1.0 + 4.0 * qD + V1
        if cand > best1:
            best1 = cand

        V0 = best0
        V1 = best1

    p_now = qC if last_my == 'C' else qD
    valC = 3.0 * p_now + V0
    valD = 1.0 + 4.0 * p_now + V1
    base = 'D' if valD >= valC else 'C'

    if rem == 1:
        return 'D'

    if opp_rate < 0.25 or opp_def_streak >= 4 or (n >= 5 and opp_c == 0):
        return 'D'

    if last_opp == 'C' and after_dc > after_dd and opp_rate > 0.65:
        return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            if n >= 3 and history[-2][0] == 'C' and history[-2][1] == 'D':
                return 'D'
            if n >= 3 and history[-2][0] == 'D' and opp_rate > 0.55:
                return 'C'
            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'C' and opp_rate > 0.55:
                return 'D'
            if opp_rate < 0.55:
                return 'D'

    if (last_my == 'C' and last_opp == 'C' and total_dr == 0 and
            opp_rate > 0.72 and my_rate > 0.72 and rem > 15 and n > 15):
        return 'D'

    return base
